using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1) Strongly-typed retrieval: returns JsonTypeInfo<T> directly
JsonTypeInfo<Person> personInfo = options.GetTypeInfo<Person>();
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

// 2) Probe without throwing: TryGetTypeInfo returns false if unavailable
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
    Console.WriteLine($"TryGetTypeInfo succeeded for Person (kind: {info!.Kind})");

// Try a type whose metadata might NOT be resolvable (custom resolver that resolves nothing)
var limited = new JsonSerializerOptions
{
    TypeInfoResolver = new NullResolver()
};

if (limited.TryGetTypeInfo(typeof(Person), out _))
    Console.WriteLine("Unexpected: NullResolver resolved Person");
else
    Console.WriteLine("TryGetTypeInfo correctly returned false for NullResolver");

// --- Types ---
record Person(string Name, int Age);

// A resolver that resolves nothing — simulates "metadata not available"
sealed class NullResolver : IJsonTypeInfoResolver
{
    public JsonTypeInfo? GetTypeInfo(Type type, JsonSerializerOptions options) => null;
}

